const std = @import("std");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const allocator = gpa.allocator();
    defer _ = gpa.deinit();

    // Cấp phát mảng động
    var list = std.ArrayList(i32).init(allocator);
    defer list.deinit(); // Luôn giải phóng khi kết thúc hàm

    try list.append(100);
    try list.append(200);
    std.debug.print("So luong phan tu: {d}\n", .{list.items.len});
}

const std = @import("std");

// Hàm Generic tạo ma trận tùy chỉnh kích thước khi biên dịch
fn Matrix(comptime T: type, comptime rows: usize, comptime cols: usize) type {
    return struct {
        data: [rows][cols]T,
    };
}

pub fn main() void {
    const Mat2x2 = Matrix(f32, 2, 2);
    var m = Mat2x2{ .data = .{ .{ 1.0, 0.0 }, .{ 0.0, 1.0 } } };
    std.debug.print("Matrix initialized!\n", .{});
}

const std = @import("std");
const net = std.net;

pub fn main() !void {
    const address = try net.Address.parseIp4("127.0.0.1", 8080);
    var server = try address.listen(.{ .reuse_address = true });
    defer server.deinit();
    std.debug.print("Server dang lang nghe tai cong 8080...\n", .{});
}

